-- GENERATED by benchmarks/tpch/scripts/qualify_queries.py from ../queries — do not edit.
-- Mixed layout: dimensions in postgresql.tpch_mixed, facts in hive.tpch.
-- TPC-H Q18: Large Volume Customer — standard form
SELECT
    c_name,
    c_custkey,
    o_orderkey,
    o_orderdate,
    o_totalprice,
    SUM(l_quantity)
FROM postgresql.tpch_mixed.customer
JOIN hive.tpch.orders ON c_custkey = o_custkey
JOIN hive.tpch.lineitem ON o_orderkey = l_orderkey
WHERE o_orderkey IN (
    SELECT l_orderkey
    FROM hive.tpch.lineitem
    GROUP BY l_orderkey
    HAVING SUM(l_quantity) > 300
)
GROUP BY c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice
ORDER BY o_totalprice DESC, o_orderdate
LIMIT 100
